arguments.content:
:root {
  --primary: #6366F1;
  --primary-dark: #4F46E5;
  --primary-light: #818CF8;
  --primary-bg: #EEF2FF;
  --secondary: #818CF8;
  --accent: #F97316;
  --accent-dark: #EA580C;
  --bg: #FFFFFF;
  --bg-alt: #F8FAFC;
  --bg-subtle: #F1F5F9;
  --text: #1E293B;
  --text-secondary: #64748B;
  --text-muted: #94A3B8;
  --border: #E2E8F0;
  --border-light: #F1F5F9;
  --card: #FFFFFF;
  --destructive: #DC2626;
  --success: #059669;
  --ring: #6366F1;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input { font-family: inherit; }

h1, h2, h3, h4, h5, h6 {
  line-height: 1.2;
  font-weight: 700;
  color: var(--text);
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); letter-spacing: -0.025em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); letter-spacing: -0.02em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { color: var(--text-secondary); line-height: 1.7; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-lg {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== NAVBAR ===== */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
  height: 64px;
}

.navbar-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.navbar-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text);
}

.navbar-logo svg { flex-shrink: 0; }

.navbar-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.navbar-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.navbar-links a:hover { color: var(--primary); }

.navbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.mobile-menu-btn {
  display: none;
  padding: 8px;
  color: var(--text);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 64px;
  left: 0;
  right: 0;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  padding: 16px 24px;
  z-index: 99;
  box-shadow: var(--shadow-lg);
}

.mobile-menu.active { display: block; }

.mobile-menu a {
  display: block;
  padding: 12px 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-light);
}

.mobile-menu a:last-child { border-bottom: none; }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 44px;
  cursor: pointer;
}

.btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
  box-shadow: 0 1px 3px rgba(99,102,241,0.3);
}

.btn-primary:hover {
  background: var(--primary-dark);
  box-shadow: 0 4px 12px rgba(99,102,241,0.35);
  transform: translateY(-1px);
}

.btn-primary:active { transform: translateY(0); }

.btn-secondary {
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  background: var(--bg-alt);
  border-color: var(--text-muted);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 10px 16px;
}

.btn-ghost:hover { color: var(--primary); background: var(--primary-bg); }

.btn-accent {
  background: var(--accent);
  color: #fff;
}

.btn-accent:hover { background: var(--accent-dark); transform: translateY(-1px); }

.btn-lg { padding: 14px 32px; font-size: 1rem; border-radius: var(--radius-md); }
.btn-sm { padding: 8px 16px; font-size: 0.875rem; min-height: 36px; }

.btn-outline-primary {
  background: transparent;
  color: var(--primary);
  border: 1.5px solid var(--primary);
}

.btn-outline-primary:hover {
  background: var(--primary);
  color: #fff;
}

/* ===== SECTIONS ===== */
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }
.section-lg { padding: 100px 0; }
.section-alt { background: var(--bg-alt); }

.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 48px;
}

.section-header h2 { margin-bottom: 16px; }
.section-header p { font-size: 1.125rem; }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  font-size: 0.8125rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  background: var(--primary-bg);
  color: var(--primary);
}

.badge-accent { background: #FFF7ED; color: var(--accent); }
.badge-success { background: #ECFDF5; color: var(--success); }

/* ===== CARDS ===== */
.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary-bg);
  color: var(--primary);
  margin-bottom: 16px;
}

/* ===== GRID SYSTEM ===== */
.grid { display: grid; gap: 24px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* ===== LOGO BAR ===== */
.logo-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 40px;
  opacity: 0.5;
}

.logo-bar span {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.01em;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--text);
  color: #CBD5E1;
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h4 {
  color: #fff;
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: #94A3B8;
  padding: 4px 0;
  transition: color var(--transition-fast);
}

.footer-col a:hover { color: #fff; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: #64748B;
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

.footer-bottom-links a { color: #64748B; }
.footer-bottom-links a:hover { color: #fff; }

/* ===== TESTIMONIALS ===== */
.testimonial-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
}

.testimonial-text {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text);
  font-style: italic;
  flex: 1;
  margin-bottom: 24px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--primary-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  font-weight: 700;
  font-size: 1rem;
}

.testimonial-info strong {
  display: block;
  font-size: 0.9375rem;
  font-weight: 600;
}

.testimonial-info span {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ===== PRICING ===== */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 40px;
}

.pricing-toggle span { font-size: 0.9375rem; font-weight: 500; color: var(--text-secondary); }
.pricing-toggle span.active { color: var(--text); font-weight: 600; }

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--primary);
  border-radius: 14px;
  cursor: pointer;
  transition: background var(--transition-base);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: #fff;
  border-radius: 50%;
  transition: transform var(--transition-base);
}

.toggle-switch.annual::after { transform: translateX(24px); }

.save-badge {
  background: #ECFDF5;
  color: var(--success);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: var(--radius-full);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  transition: all var(--transition-base);
}

.pricing-card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary), var(--shadow-lg);
}

.pricing-card.popular::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 4px 16px;
  border-radius: var(--radius-full);
}

.pricing-card h3 { font-size: 1.25rem; margin-bottom: 8px; }

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text);
  margin: 16px 0 4px;
  letter-spacing: -0.03em;
}

.pricing-price span {
  font-size: 0.9375rem;
  font-weight: 400;
  color: var(--text-secondary);
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.pricing-features {
  list-style: none;
  margin: 24px 0;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 6px 0;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.pricing-features li svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--success);
}

/* ===== FAQ ===== */
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  background: var(--card);
  cursor: pointer;
  text-align: left;
  transition: background var(--transition-fast);
}

.faq-question:hover { background: var(--bg-alt); }

.faq-question svg {
  flex-shrink: 0;
  transition: transform var(--transition-base);
  color: var(--text-muted);
}

.faq-item.active .faq-question svg { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.faq-answer-inner {
  padding: 0 24px 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.faq-item.active .faq-answer { max-height: 300px; }

/* ===== COMPARISON TABLE ===== */
.comparison-table-wrapper {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-top: 48px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.comparison-table th,
.comparison-table td {
  padding: 14px 20px;
  text-align: center;
  border-bottom: 1px solid var(--border);
}

.comparison-table th:first-child,
.comparison-table td:first-child {
  text-align: left;
  font-weight: 500;
  color: var(--text);
  min-width: 200px;
}

.comparison-table thead th {
  background: var(--bg-alt);
  font-weight: 700;
  font-size: 0.9375rem;
  color: var(--text);
}

.comparison-table tbody tr:last-child td { border-bottom: none; }

.comparison-table .check { color: var(--success); }
.comparison-table .dash { color: var(--text-muted); }

.comparison-table-collapsed { display: none; }
.comparison-table-collapsed.visible { display: table-row-group; }

/* ===== TEAM SIZE SLIDER ===== */
.slider-container {
  max-width: 500px;
  margin: 0 auto 48px;
  text-align: center;
}

.slider-container label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
  display: block;
  margin-bottom: 12px;
}

.slider-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 8px;
}

input[type="range"] {
  -webkit-appearance: none;
  width: 100%;
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(99,102,241,0.3);
}

input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 22px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  border: none;
}

input[type="range"]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 4px;
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--text);
  color: #E2E8F0;
  padding: 20px 24px;
  z-index: 1000;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
  transition: transform var(--transition-slow);
}

.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }

.cookie-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-inner p { color: #CBD5E1; font-size: 0.875rem; flex: 1; min-width: 280px; }

.cookie-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.cookie-actions .btn { font-size: 0.8125rem; padding: 8px 16px; min-height: 36px; }

.cookie-btn-accept {
  background: var(--primary);
  color: #fff;
  border-radius: var(--radius-md);
}

.cookie-btn-reject {
  background: transparent;
  color: #CBD5E1;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-md);
}

.cookie-btn-manage {
  background: transparent;
  color: #94A3B8;
  text-decoration: underline;
  border-radius: var(--radius-md);
}

/* ===== COOKIE MODAL ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1001;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-base);
}

.modal-overlay.active { opacity: 1; pointer-events: auto; }

.modal {
  background: var(--card);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 520px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: var(--shadow-xl);
}

.modal h3 { margin-bottom: 8px; }
.modal > p { font-size: 0.875rem; margin-bottom: 24px; }

.cookie-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-top: 1px solid var(--border);
}

.cookie-category-info h4 { font-size: 0.9375rem; margin-bottom: 2px; }
.cookie-category-info p { font-size: 0.8125rem; color: var(--text-muted); }

.cookie-toggle {
  position: relative;
  width: 44px;
  height: 24px;
  background: var(--border);
  border-radius: 12px;
  cursor: pointer;
  transition: background var(--transition-fast);
  flex-shrink: 0;
}

.cookie-toggle.active { background: var(--primary); }

.cookie-toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 20px;
  height: 20px;
  background: #fff;
  border-radius: 50%;
  transition: transform var(--transition-fast);
}

.cookie-toggle.active::after { transform: translateX(20px); }

.cookie-toggle.disabled {
  opacity: 0.6;
  cursor: not-allowed;
  background: var(--primary);
}

.cookie-toggle.disabled::after { transform: translateX(20px); }

.modal-actions {
  margin-top: 24px;
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

/* ===== AUTH PAGES ===== */
.auth-page {
  min-height: 100vh;
  display: flex;
}

.auth-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
}

.auth-form {
  width: 100%;
  max-width: 400px;
}

.auth-form h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  text-align: center;
}

.auth-form .subtitle {
  text-align: center;
  margin-bottom: 32px;
  font-size: 0.9375rem;
}

.social-buttons {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  background: var(--bg);
  color: var(--text);
  transition: all var(--transition-fast);
  min-height: 44px;
  width: 100%;
  cursor: pointer;
}

.social-btn:hover { background: var(--bg-alt); border-color: var(--text-muted); }

.social-btn svg { flex-shrink: 0; }

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 0 0 24px;
  color: var(--text-muted);
  font-size: 0.8125rem;
}

.divider::before, .divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

.form-group { margin-bottom: 16px; }

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text);
  margin-bottom: 6px;
}

.form-group input {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--text);
  background: var(--bg);
  transition: border-color var(--transition-fast);
  min-height: 44px;
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99,102,241,0.1);
}

