.pricing-toggle span { font-size: 0.9375rem; font-weight: 500; color: var(--text-secondary); }
.pricing-toggle span.active { color: var(--text); font-weight: 600; }

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--primary);
  border-radius: 14px;
  cursor: pointer;
  transition: background var(--transition-base);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: #fff;
  border-radius: 50%;
  transition: transform var(--transition-base);
}

.toggle-switch.annual::after { transform: translateX(24px); }

.save-badge {
  background: #ECFDF5;
  color: var(--success);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: var(--radius-full);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  transition: all var(--transition-base);
}

.pricing-card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary), var(--shadow-lg);
}

.pricing-card.popular::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 4px 16px;
  border-radius: var(--radius-full);
}

.pricing-card h3 { font-size: 1.25rem; margin-bottom: 8px; }

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text);
  margin: 16px 0 4px;
  letter-spacing: -0.03em;
}

.pricing-price span {
  font-size: 0.9375rem;
  font-weight: 400;
  color: var(--text-secondary);
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.pricing-features {
  list-style: none;
  margin: 24px 0;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 6px 0;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.pricing-features li svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--success);
}

/* ===== FAQ ===== */
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  background: var(--card);
  cursor: pointer;
  text-align: left;
  transition: background var(--transition-fast);
}

.faq-question:hover { background: var(--bg-alt); }

.faq-question svg {
  flex-shrink: 0;
  transition: transform var(--transition-base);
  color: var(--text-muted);
}

.faq-item.active .faq-question svg { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.faq-answer-inner {
  padding: 0 24px 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.faq-item.active .faq-answer { max-height: 300px; }

/* ===== COMPARISON TABLE ===== */
.comparison-table-wrapper {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-top: 48px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.comparison-table th,
.comparison-table td {
  padding: 14px 20px;
  text-align: center;
  border-bottom: 1px solid var(--border);
}

.comparison-table th:first-child,
.comparison-table td:first-child {
  text-align: left;
  font-weight: 500;
  color: var(--text);
  min-width: 200px;
}

.comparison-table thead th {
  background: var(--bg-alt);
  font-weight: 700;
  font-size: 0.9375rem;
  color: var(--text);
}

.comparison-table tbody tr:last-child td { border-bottom: none; }

.comparison-table .check { color: var(--success); }
.comparison-table .dash { color: var(--text-muted); }

.comparison-table-collapsed { display: none; }
.comparison-table-collapsed.visible { display: table-row-group; }

/* ===== TEAM SIZE SLIDER ===== */
.slider-container {
  max-width: 500px;
  margin: 0 auto 48px;
  text-align: center;
}

.slider-container label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
  display: block;
  margin-bottom: 12px;
}

.slider-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 8px;
}

input[type="range"] {
  -webkit-appearance: none;
  width: 100%;
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(99,102,241,0.3);
}

input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 22px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  border: none;
}

input[type="range"]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 4px;
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--text);
  color: #E2E8F0;
  padding: 20px 24px;
  z-index: 1000;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
  transition: transform var(--transition-slow);
}

.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }

.cookie-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-inner p { color: #CBD5E1; font-size: 0.875rem; flex: 1; min-width: 280px; }

.cookie-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.cookie-actions .btn { font-size: 0.8125rem; padding: 8px 16px; min-height: 36px; }

.cookie-btn-accept {
  background: var(--primary);
  color: #fff;
  border-radius: var(--radius-md);
}

.cookie-btn-reject {
  background: transparent;
  color: #CBD5E1;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-md);
}

.cookie-btn-manage {
  background: transparent;
  color: #94A3B8;
  text-decoration: underline;
  border-radius: var(--radius-md);
}

/* ===== COOKIE MODAL ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1001;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-base);
}

.modal-overlay.active { opacity: 1; pointer-events: auto; }

.modal {
  background: var(--card);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 520px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: var(--shadow-xl);
}

.modal h3 { margin-bottom: 8px; }
.modal > p { font-size: 0.875rem; margin-bottom: 24px; }

.cookie-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-top: 1px solid var(--border);
}

.cookie-category-info h4 { font-size: 0.9375rem; margin-bottom: 2px; }
.cookie-category-info p { font-size: 0.8125rem; color: var(--text-muted); }

.cookie-toggle {
  position: relative;
  width: 44px;
  height: 24px;
  background: var(--border);
  border-radius: 12px;
  cursor: pointer;
  transition: background var(--transition-fast);
  flex-shrink: 0;
}

.cookie-toggle.active { background: var(--primary); }

.cookie-toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 20px;
  height: 20px;
  background: #fff;
  border-radius: 50%;
  transition: transform var(--transition-fast);
}

.cookie-toggle.active::after { transform: translateX(20px); }

.cookie-toggle.disabled {
  opacity: 0.6;
  cursor: not-allowed;
  background: var(--primary);
}

.cookie-toggle.disabled::after { transform: translateX(20px); }

.modal-actions {
  margin-top: 24px;
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

/* ===== AUTH PAGES ===== */
.auth-page {
  min-height: 100vh;
  display: flex;
}

.auth-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
}

.auth-form {
  width: 100%;
  max-width: 400px;
}

.auth-form h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  text-align: center;
}

.auth-form .subtitle {
  text-align: center;
  margin-bottom: 32px;
  font-size: 0.9375rem;
}

.social-buttons {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  background: var(--bg);
  color: var(--text);
  transition: all var(--transition-fast);
  min-height: 44px;
  width: 100%;
  cursor: pointer;
}

.social-btn:hover { background: var(--bg-alt); border-color: var(--text-muted); }

.social-btn svg { flex-shrink: 0; }

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 0 0 24px;
  color: var(--text-muted);
  font-size: 0.8125rem;
}

.divider::before, .divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

.form-group { margin-bottom: 16px; }

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text);
  margin-bottom: 6px;
}

.form-group input {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--text);
  background: var(--bg);
  transition: border-color var(--transition-fast);
  min-height: 44px;
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99,102,241,0.1);
}

.form-group input::placeholder { color: var(--text-muted); }

.auth-footer {
  text-align: center;
  margin-top: 24px;
  font-size: 0.8125rem;
  color: var(--text-muted);
  line-height: 1.6;
}

.auth-footer a {
  color: var(--primary);
  font-weight: 500;
}

.auth-footer a:hover { text-decoration: underline; }

.auth-sidebar {
  width: 480px;
  background: linear-gradient(135deg, #4F46E5 0%, #6366F1 50%, #818CF8 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px;
  color: #fff;
}

.auth-sidebar blockquote {
  font-size: 1.25rem;
  line-height: 1.6;
  font-style: italic;
  margin-bottom: 24px;
  opacity: 0.95;
}

.auth-sidebar cite {
  font-style: normal;
  font-size: 0.9375rem;
  opacity: 0.8;
}

.auth-sidebar cite strong { display: block; font-size: 1rem; opacity: 1; }

/* ===== HERO ===== */
.hero {
  padding: 80px 0 60px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero-gradient {
  background: linear-gradient(180deg, var(--primary-bg) 0%, var(--bg) 100%);
}

.hero h1 { margin-bottom: 20px; max-width: 800px; margin-left: auto; margin-right: auto; }
.hero p { font-size: 1.25rem; max-width: 640px; margin: 0 auto 32px; }

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.hero-visual {
  margin-top: 56px;
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
  background: linear-gradient(135deg, #4F46E5 0%, #818CF8 100%);
  border-radius: var(--radius-xl);
  padding: 32px;
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-xl);
  position: relative;
}

.hero-visual-inner {
  width: 100%;
  height: 100%;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  border: 1px solid rgba(255,255,255,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
}

.play-button {
  width: 72px;
  height: 72px;
  background: rgba(255,255,255,0.95);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 32px rgba(0,0,0,0.15);
}

.play-button svg { color: var(--primary); margin-left: 4px; }

/* ===== STATS ===== */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item h3 {
  font-size: clamp(2rem, 4vw, 3rem);
  color: var(--primary);
  margin-bottom: 8px;
}

.stat-item p { font-size: 1rem; }

/* ===== USE CASES ===== */
.use-case-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}

.use-case-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--primary-bg);
}

.use-case-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: var(--primary-bg);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}

.use-case-card h3 { margin-bottom: 10px; }
.use-case-card p { font-size: 0.9375rem; }

/* ===== FEATURE SPLIT ===== */
.feature-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-split-reverse { direction: rtl; }
.feature-split-reverse > * { direction: ltr; }

.feature-content .badge { margin-bottom: 16px; }
.feature-content h2 { margin-bottom: 16px; }
.feature-content p { margin-bottom: 24px; }

.feature-visual {
  background: var(--bg-alt);
  border-radius: var(--radius-xl);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid var(--border);
}

.feature-visual-gradient {
  background: linear-gradient(135deg, #EEF2FF 0%, #E0E7FF 100%);
}

/* ===== AI FEATURES ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.ai-feature {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.ai-feature:hover { background: var(--bg-alt); }

.ai-feature svg { flex-shrink: 0; color: var(--primary); margin-top: 2px; }

.ai-feature-text h4 { font-size: 0.9375rem; margin-bottom: 2px; }
.ai-feature-text .badge { font-size: 0.6875rem; padding: 1px 6px; }

/* ===== INTEGRATIONS ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 20px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.integration-item:hover { background: var(--bg-alt); border-color: var(--primary-bg); }

.integration-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--primary);
}

.integration-item span { font-size: 0.8125rem; color: var(--text-secondary); font-weight: 500; }

/* ===== CTA BANNER ===== */
.cta-banner {
  background: linear-gradient(135deg, #4F46E5 0%, #6366F1 50%, #818CF8 100%);
  border-radius: var(--radius-xl);
  padding: 64px 48px;
  text-align: center;
  color: #fff;
}

.cta-banner h2 { color: #fff; margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.8); margin-bottom: 32px; font-size: 1.125rem; }

.cta-banner .btn-primary {
  background: #fff;
  color: var(--primary);
  box-shadow: 0 4px 16px rgba(0,0,0,0.15);
}

.cta-banner .btn-primary:hover {
  background: #F8FAFC;
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
}

/* ===== BLOG TEASER ===== */
.blog-card {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}

.blog-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.blog-card-image {
  height: 200px;
  background: linear-gradient(135deg, #E0E7FF 0%, #C7D2FE 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.blog-card-content {
  padding: 24px;
}

.blog-card-content h3 { font-size: 1.125rem; margin-bottom: 10px; }
.blog-card-content p { font-size: 0.875rem; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .pricing-cards { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .feature-split { grid-template-columns: 1fr; gap: 40px; }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .auth-sidebar { display: none; }
  .ai-features-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .section { padding: 56px 0; }
  .section-lg { padding: 72px 0; }
  .navbar-links { display: none; }
  .mobile-menu-btn { display: block; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .pricing-cards { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .hero { padding: 48px 0 40px; }
  .hero-visual { margin-top: 40px; padding: 16px; }
  .logo-bar { gap: 24px; }
  .cta-banner { padding: 40px 24px; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .comparison-table th:first-child, .comparison-table td:first-child { min-width: 140px; }
  .ai-features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .hero-actions { flex-direction: column; width: 100%; }
  .hero-actions .btn { width: 100%; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ===== SKIP LINK ===== */
.skip-link {
  position: absolute;
  top: -100px;
  left: 16px;
  background: var(--primary);
  color: #fff;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  z-index: 200;
  font-weight: 600;
  transition: top var(--transition-fast);
}

.skip-link:focus { top: 16px; }

/* ===== SECURITY GRID ===== */
.security-features {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.security-item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.security-item:hover { background: var(--bg-alt); }

.security-item svg { flex-shrink: 0; color: var(--success); margin-top: 2px; }

.security-item h4 { margin-bottom: 4px; }
.security-item p { font-size: 0.875rem; }

/* ===== FEATURE LIST ===== */
.feature-list { list-style: none; }

.feature-list li {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 12px 0;
}

.feature-list li svg { flex-shrink: 0; color: var(--primary); margin-top: 4px; }
.feature-list li strong { display: block; margin-bottom: 4px; }
.feature-list li p { font-size: 0.9375rem; }

/* ===== ENGAGEMENT / BENEFIT CARDS ===== */
.benefit-card {
  padding: 32px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--card);
}

.benefit-card h3 { margin-bottom: 12px; }
.benefit-card p { font-size: 0.9375rem; }

.benefit-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--primary-bg);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
